                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        todo.append((yy, xx))
            marks = [(y, x) for y, x in cells if grid[y][x] == 9]
            comps.append((cells, marks))

    # The panel to clear is the one with the smallest nonzero number of marks.
    # In ties, choose the panel with the smallest area.
    candidates = [item for item in comps if item[1]]
    if candidates:
        cells, marks = min(candidates, key=lambda item: (len(item[1]), len(item[0])))
        for y, x in cells:
